css:
.sl-footer-support {
    padding-top: 4.5rem;
    font-family: var(--smartlearn-body-font, inherit);
}
.sl-footer-support .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-footer-support .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-footer-support .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-footer-support.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-footer-support .sl-bg-card { background-color: var(--smartlearn-card-bg) !important; }
.sl-footer-support .sl-icon-subtle {
    background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent) !important;
}
.sl-footer-support.sl-border,
.sl-footer-support .border.sl-border,
.sl-footer-support .border-bottom.sl-border,
.sl-footer-support .pt-4.sl-border { border-color: var(--smartlearn-card-border) !important; }

.sl-footer-support .sl-icon-circle { width: 48px; height: 48px; }
.sl-footer-support .sl-footer-link { transition: color 0.2s ease; }
.sl-footer-support .sl-footer-link:hover,
.sl-footer-support .sl-footer-link:focus-visible {
    color: var(--smartlearn-primary) !important;
    text-decoration: underline !important;
}
.sl-footer-support a:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .sl-footer-support .sl-footer-link { transition: none; }
}
